contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Deposit 'amount' into c, then call withdrawAll. Assert that either withdraw succeeded and
    // this contract's balance increased by at least 'amount' (and c's balance decreased accordingly),
    // or withdraw reverted and both balances are unchanged from after deposit.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance to fund deposit");

        // record balances before any action
        uint beforeTestBalance = address(this).balance;
        uint beforeCBalance = address(c).balance;

        // perform deposit
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // balances immediately after deposit
        uint afterDepositTestBalance = address(this).balance;
        uint afterDepositCBalance = address(c).balance;

        // attempt withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterWithdrawTestBalance = address(this).balance;
        uint afterWithdrawCBalance = address(c).balance;

        // General property:
        // If withdrawAll reverted, balances must equal their values immediately after deposit.
        // If withdrawAll succeeded, this contract's balance must have increased by at least 'amount'
        // compared to afterDepositTestBalance, and c's balance must have decreased by at least 'amount'
        // compared to afterDepositCBalance.
        assert(
            (reverted && afterWithdrawTestBalance == afterDepositTestBalance && afterWithdrawCBalance == afterDepositCBalance)
            ||
            (!reverted && afterWithdrawTestBalance >= afterDepositTestBalance + amount && afterWithdrawCBalance + amount <= afterDepositCBalance)
        );
    }

    // accept Ether if sent back
    receive() external payable {}
}

