pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint beforeTestBalance = address(this).balance;
        uint beforeCBalance = address(c).balance;
        try c.deposit{value: amount}() {} catch { return; }
        uint afterDepositTestBalance = address(this).balance;
        uint afterDepositCBalance = address(c).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterWithdrawTestBalance = address(this).balance;
        uint afterWithdrawCBalance = address(c).balance;
        assertTrue((reverted && afterWithdrawTestBalance == afterDepositTestBalance && afterWithdrawCBalance == afterDepositCBalance)
            ||
            (!reverted && afterWithdrawTestBalance >= afterDepositTestBalance + amount && afterWithdrawCBalance + amount <= afterDepositCBalance));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
